`timescale 1ns/1ps
`default_nettype none
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md (zero wait states, no state machine,
// PSLVERR for unmapped addresses) for interface_spec.md.
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output reg  [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    // ------------------------------------------------------------------
    // Transfer decode
    // ------------------------------------------------------------------
    // Access phase: the one cycle in which the response is sampled and a
    // write takes effect (pready is always high).
    wire access = psel && penable;

    // Mapped: word aligned and within 0x0..0xC.
    wire mapped = (paddr[1:0] == 2'b00) &&
                  (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

    wire [1:0] idx = paddr[3:2];

    wire wr_en = access && pwrite && mapped;
    wire rd_en = access && !pwrite && mapped;

    wire we0 = wr_en && (idx == 2'd0);
    wire we1 = wr_en && (idx == 2'd1);
    wire we2 = wr_en && (idx == 2'd2);
    wire we3 = wr_en && (idx == 2'd3);

    // Byte-lane write mask from pstrb.
    wire [DATA_WIDTH-1:0] wmask;
    genvar g;
    generate
        for (g = 0; g < DATA_WIDTH/8; g = g + 1) begin : g_wmask
            assign wmask[8*g +: 8] = {8{pstrb[g]}};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Register file: four separate flops, synchronous active-low reset
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            if (we0) reg0 <= (reg0 & ~wmask) | (pwdata & wmask);
            if (we1) reg1 <= (reg1 & ~wmask) | (pwdata & wmask);
            if (we2) reg2 <= (reg2 & ~wmask) | (pwdata & wmask);
            if (we3) reg3 <= (reg3 & ~wmask) | (pwdata & wmask);
        end
    end

    // ------------------------------------------------------------------
    // Responses
    // ------------------------------------------------------------------
    assign pready  = 1'b1;
    assign pslverr = access && !mapped;

    // Read data: zero unless this is a mapped read access.
    always @* begin
        prdata = {DATA_WIDTH{1'b0}};
        if (rd_en) begin
            case (idx)
                2'd0:    prdata = reg0;
                2'd1:    prdata = reg1;
                2'd2:    prdata = reg2;
                2'd3:    prdata = reg3;
                default: prdata = {DATA_WIDTH{1'b0}};
            endcase
        end
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (read with read -formal)
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    wire f_access = psel && penable;
    // Independent decode, written apart from 'mapped'.
    wire f_mapped = (paddr < 16) && (paddr[1:0] == 2'b00);

    // Manager assumptions
    always @(*) begin
        if (!f_past_valid) assume(!presetn);
        if (!presetn)      assume(!psel);
        if (penable)       assume(psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid) begin
            if (psel && penable) begin
                assume($past(psel && !penable));
                assume(paddr  == $past(paddr));
                assume(pwrite == $past(pwrite));
                assume(pwdata == $past(pwdata));
                assume(pstrb  == $past(pstrb));
            end
            if ($past(psel && penable))
                assume(!penable);
            if ($past(presetn && psel && !penable))
                assume(psel && penable);
        end
    end

    // Response assertions
    always @(*) begin
        assert(pready);
        if (!f_access) begin
            assert(prdata == 0);
            assert(!pslverr);
        end else begin
            assert(pslverr == !f_mapped);
            if (pwrite || !f_mapped)
                assert(prdata == 0);
            else if (paddr[3:2] == 2'd0)
                assert(prdata == reg0);
            else if (paddr[3:2] == 2'd1)
                assert(prdata == reg1);
            else if (paddr[3:2] == 2'd2)
                assert(prdata == reg2);
            else
                assert(prdata == reg3);
        end
    end

    // Registers are zero after reset
    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn)) begin
            assert(reg0 == 0);
            assert(reg1 == 0);
            assert(reg2 == 0);
            assert(reg3 == 0);
        end
    end

    // Each byte changes only in a mapped write access to its register
    // with its strobe set, and then to the written byte.
    genvar fb;
    generate
        for (fb = 0; fb < DATA_WIDTH/8; fb = fb + 1) begin : g_fbyte
            always @(posedge pclk) begin
                if (f_past_valid && $past(presetn)) begin
                    if ($past(f_access && pwrite && f_mapped && (paddr[3:2] == 2'd0) && pstrb[fb]))
                        assert(reg0[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg0[8*fb +: 8] == $past(reg0[8*fb +: 8]));
                    if ($past(f_access && pwrite && f_mapped && (paddr[3:2] == 2'd1) && pstrb[fb]))
                        assert(reg1[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg1[8*fb +: 8] == $past(reg1[8*fb +: 8]));
                    if ($past(f_access && pwrite && f_mapped && (paddr[3:2] == 2'd2) && pstrb[fb]))
                        assert(reg2[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg2[8*fb +: 8] == $past(reg2[8*fb +: 8]));
                    if ($past(f_access && pwrite && f_mapped && (paddr[3:2] == 2'd3) && pstrb[fb]))
                        assert(reg3[8*fb +: 8] == $past(pwdata[8*fb +: 8]));
                    else
                        assert(reg3[8*fb +: 8] == $past(reg3[8*fb +: 8]));
                end
            end
        end
    endgenerate

    // Covers: a register written and read back, and an error response
    always @(posedge pclk) begin
        if (f_past_valid && presetn) begin
            cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd3) &&
                  (prdata == 32'h1234_5678));
            cover(f_access && pslverr);
        end
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
