`timescale 1ns/1ps
`default_nettype none
// Self-checking directed testbench for apb_regs (default parameters).
// Inputs are driven after the falling edge and checked 1 time unit later,
// before the rising edge.
module apb_regs_tb;

    localparam integer AW = 8;
    localparam integer DW = 32;
    localparam integer SW = DW/8;

    reg           pclk;
    reg           presetn;
    reg  [AW-1:0] paddr;
    reg           psel;
    reg           penable;
    reg           pwrite;
    reg  [DW-1:0] pwdata;
    reg  [SW-1:0] pstrb;
    wire [DW-1:0] prdata;
    wire          pready;
    wire          pslverr;

    apb_regs #(
        .ADDR_WIDTH(AW),
        .DATA_WIDTH(DW)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    integer passed;
    integer failed;
    integer rc;
    integer i;
    integer r;

    reg [DW-1:0] model0;
    reg [DW-1:0] model1;
    reg [DW-1:0] model2;
    reg [DW-1:0] model3;

    reg [8*64-1:0] nonce;
    reg [DW-1:0]   data_v;
    reg [AW-1:0]   addr_v;
    reg [SW-1:0]   strb_v;

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ------------------------------------------------------------------
    // Reference model
    // ------------------------------------------------------------------
    function [DW-1:0] merge;
        input [DW-1:0] old;
        input [DW-1:0] data;
        input [SW-1:0] strb;
        integer b;
        begin
            merge = old;
            for (b = 0; b < SW; b = b + 1)
                if (strb[b]) merge[8*b +: 8] = data[8*b +: 8];
        end
    endfunction

    function tb_mapped;
        input [AW-1:0] a;
        begin
            tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    function [DW-1:0] model_read;
        input [AW-1:0] a;
        begin
            if (!tb_mapped(a)) begin
                model_read = {DW{1'b0}};
            end else begin
                case (a[3:2])
                    2'd0:    model_read = model0;
                    2'd1:    model_read = model1;
                    2'd2:    model_read = model2;
                    2'd3:    model_read = model3;
                    default: model_read = {DW{1'b0}};
                endcase
            end
        end
    endfunction

    task model_write;
        input [AW-1:0] a;
        input [DW-1:0] d;
        input [SW-1:0] s;
        begin
            if (tb_mapped(a)) begin
                case (a[3:2])
                    2'd0:    model0 = merge(model0, d, s);
                    2'd1:    model1 = merge(model1, d, s);
                    2'd2:    model2 = merge(model2, d, s);
                    2'd3:    model3 = merge(model3, d, s);
                    default: model0 = model0;
                endcase
            end
        end
    endtask

    task model_reset;
        begin
            model0 = {DW{1'b0}};
            model1 = {DW{1'b0}};
            model2 = {DW{1'b0}};
            model3 = {DW{1'b0}};
        end
    endtask

    // ------------------------------------------------------------------
    // Checks
    // ------------------------------------------------------------------
    task check_bit;
        input          got;
        input          exp;
        input [8*24-1:0] what;
        begin
            if (got !== exp) begin
                $error("%0t %0s: got %b expected %b (paddr=%h)", $time, what, got, exp, paddr);
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    task check_word;
        input [DW-1:0]   got;
        input [DW-1:0]   exp;
        input [8*24-1:0] what;
        begin
            if (got !== exp) begin
                $error("%0t %0s: got %h expected %h (paddr=%h)", $time, what, got, exp, paddr);
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    task check_quiet;
        input [8*24-1:0] what;
        begin
            check_word(prdata, {DW{1'b0}}, what);
            check_bit(pslverr, 1'b0, what);
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks: each starts at a falling edge and ends at a rising edge
    // ------------------------------------------------------------------
    task apb_xfer;
        input          wr;
        input [AW-1:0] a;
        input [DW-1:0] d;
        input [SW-1:0] s;
        reg   [DW-1:0] exp_rd;
        reg            exp_err;
        begin
            exp_err = !tb_mapped(a);
            exp_rd  = wr ? {DW{1'b0}} : model_read(a);
            // Setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = wr;
            paddr   = a;
            pwdata  = wr ? d : {DW{1'b0}};
            pstrb   = wr ? s : {SW{1'b0}};
            #1;
            check_quiet("setup quiet");
            // Access phase: must complete in its first cycle
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check_bit(pready, 1'b1, "access pready");
            check_bit(pslverr, exp_err, "access pslverr");
            check_word(prdata, exp_rd, "access prdata");
            @(posedge pclk);
            if (wr) model_write(a, d, s);
        end
    endtask

    task apb_write;
        input [AW-1:0] a;
        input [DW-1:0] d;
        input [SW-1:0] s;
        begin
            apb_xfer(1'b1, a, d, s);
        end
    endtask

    task apb_read;
        input [AW-1:0] a;
        begin
            apb_xfer(1'b0, a, {DW{1'b0}}, {SW{1'b0}});
        end
    endtask

    task idle;
        input integer n;
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = 1'b0;
                paddr   = {AW{1'b0}};
                pwdata  = {DW{1'b0}};
                pstrb   = {SW{1'b0}};
                #1;
                check_quiet("idle quiet");
                @(posedge pclk);
            end
        end
    endtask

    task do_reset;
        integer k;
        begin
            @(negedge pclk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = {AW{1'b0}};
            pwdata  = {DW{1'b0}};
            pstrb   = {SW{1'b0}};
            presetn = 1'b0;
            for (k = 0; k < 3; k = k + 1) begin
                #1;
                check_quiet("reset quiet");
                @(negedge pclk);
            end
            presetn = 1'b1;
            model_reset;
        end
    endtask

    task read_all;
        begin
            apb_read(8'h00);
            apb_read(8'h04);
            apb_read(8'h08);
            apb_read(8'h0C);
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed  = 0;
        failed  = 0;
        nonce   = {(8*64){1'b0}};
        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = {AW{1'b0}};
        pwdata  = {DW{1'b0}};
        pstrb   = {SW{1'b0}};
        data_v  = 32'h1357_9BDF;
        addr_v  = {AW{1'b0}};
        strb_v  = {SW{1'b0}};
        model_reset;

        // 1. Reset values
        do_reset;
        read_all;
        idle(2);

        // 2. Write then read every register, with idle gaps
        apb_write(8'h00, 32'h1111_1111, 4'hF); idle(1);
        apb_write(8'h04, 32'h2222_2222, 4'hF); idle(1);
        apb_write(8'h08, 32'h3333_3333, 4'hF); idle(1);
        apb_write(8'h0C, 32'h4444_4444, 4'hF); idle(3);
        apb_read(8'h00); idle(1);
        apb_read(8'h04); idle(1);
        apb_read(8'h08); idle(1);
        apb_read(8'h0C); idle(2);

        // 3. Back-to-back transfers
        apb_write(8'h00, 32'hDEAD_BEEF, 4'hF);
        apb_write(8'h04, 32'hCAFE_F00D, 4'hF);
        apb_write(8'h08, 32'h0123_4567, 4'hF);
        apb_write(8'h0C, 32'h89AB_CDEF, 4'hF);
        read_all;
        apb_write(8'h08, 32'hA5A5_5A5A, 4'hF);
        apb_read(8'h08);
        apb_read(8'h00);
        apb_write(8'h00, 32'h0F0F_F0F0, 4'hF);
        apb_read(8'h00);
        apb_read(8'h0C);
        idle(1);

        // 4. Every pstrb pattern on every register, including none
        for (r = 0; r < 4; r = r + 1) begin
            addr_v = {r[5:0], 2'b00};
            for (i = 0; i < 16; i = i + 1) begin
                data_v = data_v * 32'd1103515245 + 32'd12345;
                strb_v = i[3:0];
                apb_write(addr_v, data_v, strb_v);
                apb_read(addr_v);
            end
            idle(1);
        end
        read_all;
        idle(1);

        // 5. Zero-strobe mapped write: no change, no error
        apb_write(8'h04, 32'hFFFF_FFFF, 4'h0);
        apb_read(8'h04);
        idle(1);

        // 6. PSLVERR policy: misaligned addresses inside the map
        apb_write(8'h01, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h02, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h03, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h05, 32'hEEEE_EEEE, 4'hF);
        apb_write(8'h06, 32'hEEEE_EEEE, 4'hF);
        apb_write(8'h07, 32'hEEEE_EEEE, 4'hF);
        apb_write(8'h09, 32'hDDDD_DDDD, 4'hF);
        apb_write(8'h0A, 32'hDDDD_DDDD, 4'hF);
        apb_write(8'h0B, 32'hDDDD_DDDD, 4'hF);
        apb_write(8'h0D, 32'hCCCC_CCCC, 4'hF);
        apb_write(8'h0E, 32'hCCCC_CCCC, 4'hF);
        apb_write(8'h0F, 32'hCCCC_CCCC, 4'hF);
        read_all;
        apb_read(8'h01);
        apb_read(8'h02);
        apb_read(8'h03);
        apb_read(8'h06);
        apb_read(8'h0B);
        apb_read(8'h0F);
        idle(1);

        // 7. PSLVERR policy: out of range, including alias candidates
        apb_write(8'h10, 32'hBBBB_BBBB, 4'hF);
        apb_write(8'h14, 32'hBBBB_BBBB, 4'hF);
        apb_write(8'h18, 32'hBBBB_BBBB, 4'hF);
        apb_write(8'h1C, 32'hBBBB_BBBB, 4'hF);
        apb_write(8'h11, 32'hBBBB_BBBB, 4'hF);
        apb_write(8'h40, 32'hAAAA_AAAA, 4'hF);
        apb_write(8'h80, 32'hAAAA_AAAA, 4'hF);
        apb_write(8'hF0, 32'hAAAA_AAAA, 4'hF);
        apb_write(8'hFC, 32'hAAAA_AAAA, 4'hF);
        apb_write(8'hFF, 32'hAAAA_AAAA, 4'hF);
        apb_write(8'h20, 32'h9999_9999, 4'h0);
        read_all;
        apb_read(8'h10);
        apb_read(8'h14);
        apb_read(8'h1C);
        apb_read(8'h80);
        apb_read(8'hFC);
        apb_read(8'hFF);
        idle(1);

        // 8. Mapped and unmapped interleaved back to back
        apb_write(8'h0C, 32'h7654_3210, 4'hF);
        apb_write(8'h1C, 32'hFFFF_FFFF, 4'hF);
        apb_read(8'h0C);
        apb_read(8'h4C);
        apb_write(8'h0D, 32'h0000_0000, 4'hF);
        apb_read(8'h0C);
        idle(2);

        // 9. Reset again after traffic
        apb_write(8'h00, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h04, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h08, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h0C, 32'hFFFF_FFFF, 4'hF);
        idle(1);
        do_reset;
        read_all;
        apb_write(8'h08, 32'h5555_AAAA, 4'h3);
        apb_read(8'h08);
        idle(2);

        // Verdict
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
